int main(int argc, char** argv){

    ofstream file("./pixels.rgb", ios::binary);

    if(!file){
        cout<< "ERROR CREATING THE FILE" << endl;
        exit(-1);
    }


    for (int i = 0; i < pixels.size(); i++){
        for(int j = 0; j < 3; j++){
            file.put((char)pixels[i][j]);
        }
    }



    return 0;
}


